import{_ as n,l as t,o as e,c as d,v as o,p as l,x as i,d as s,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Diamond–Dybvig 原文","description":"","frontmatter":{"title":"Diamond–Dybvig 原文","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/diamond-dybvig-paper.md","filePath":"econ/diamond-dybvig-paper.md","lastUpdated":1789023840000}'),E={name:"econ/diamond-dybvig-paper.md"};function c(h,a,D,f,b,A){const r=t("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="diamond–dybvig-原文" tabindex="-1">Diamond–Dybvig 原文 <a class="header-anchor" href="#diamond–dybvig-原文" aria-label="Permalink to &quot;Diamond–Dybvig 原文&quot;">​</a></h1><div class="epigraph"><p>活期存款提供流动性保险；同一合同在序贯服务下容许挤兑。存款保险可以去掉坏均衡。</p><footer>—— Diamond and Dybvig, Bank Runs, Deposit Insurance, and Liquidity, Journal of Political Economy 1983</footer></div><p><a href="/econ/woodford-interest">上一课</a>（Woodford 利息与价格）。附录对照。主干<a href="/econ/diamond-dybvig">Diamond–Dybvig 挤兑</a>已取三期技术、双均衡与保险。本篇对照 <strong>1983 原文</strong>多出来的问题设定：为什么政府保险或暂停兑付被写成与银行合同配套的政策，而不是另起一套货币理论；以及原文对「挤兑由什么触发」说了什么、没说什么。不重推 \\(r_1\\) 的最优保险公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Gurley–Shaw 式的中介故事不能区分「好的流动性转换」与「脆弱」。Diamond 与 Dybvig 要一张可计算的活期合同：在不可验证的个人流动性冲击下实施风险分担，并证明同一张合同是挤兑博弈。原文标题把三件事并列——挤兑、存款保险、流动性——因为政策不是外挂：保险或暂停兑付的作用是删掉坏均衡，使保险合同能够被使用。</p><p>与 <a href="/econ/woodford-interest">Woodford</a> 的对照：利息与价格假定银行部门已在，讨论的是利率规则；本文假定没有法定货币操作，讨论的是存款合同本身。两篇附录不要互相翻译成对方的模型。</p><p><span class="marginnote">原文第三节用太阳黑子选择均衡；挤兑不必有资产质量消息。暂停兑付（suspension of convertibility）与存款保险是并列的去坏均衡工具。模型没有央行资产负债表，没有准备金账户。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三期、一种长期技术、\\(t=1\\) 清算有成本。代理人类型在 \\(t=1\\) 私有。银行是互惠的活期安排，不是追求特许权价值的股权企业。序贯服务约束被明确写成：兑付按到达次序，不能把 \\(t=1\\) 的总需求当作可观察的总量再按比例分配。均衡是纳什：耐心者是否提款取决于对他人提款的信念。</p><p>政策实验在同一博弈上做。保险保证耐心者在 \\(t=2\\) 仍按合同受偿，于是坏均衡不再是最优反应。暂停兑付在达到急躁者份额后停止支付，同样保护剩余资产。原文讨论税收融资的保险，不讨论资本充足——资本是主干<a href="/econ/basel-capital">巴塞尔</a>的后起语言。</p>',10)),(e(),l(m,null,{default:i(()=>[p(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CON%5B%22%E6%B4%BB%E6%9C%9F%E5%90%88%E5%90%8C%20%2B%20%E5%BA%8F%E8%B4%AF%E6%9C%8D%E5%8A%A1%22%5D%20--%3E%20TWO%5B%22%E5%A5%BD%E5%9D%87%E8%A1%A1%20%2F%20%E6%8C%A4%E5%85%91%E5%9D%87%E8%A1%A1%22%5D%0A%20%20INS%5B%22%E5%AD%98%E6%AC%BE%E4%BF%9D%E9%99%A9%22%5D%20--%3E%20ONE%5B%22%E5%8F%AA%E7%95%99%E5%A5%BD%E5%9D%87%E8%A1%A1%22%5D%0A%20%20SUS%5B%22%E6%9A%82%E5%81%9C%E5%85%91%E4%BB%98%22%5D%20--%3E%20ONE%0A%20%20TWO%20--%3E%20POL%5B%22%E6%94%BF%E7%AD%96%20%3D%20%E6%94%B9%E5%8D%9A%E5%BC%88%2C%20%E4%B8%8D%E6%98%AF%E9%80%81%E8%B5%84%E6%9C%AC%22%5D%0A%20%20ONE%20--%3E%20POL%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>原文机制与主干相同，附录只强调两处常被课堂删掉的限定。第一，银行可以是被动的资产池，脆弱性来自负债合同，不来自经理的隐藏行动——与<a href="/econ/moral-hazard">道德风险</a>分流。第二，均衡选择可以与基本面无关；后来文献把坏消息写成触发器，是对原文的补充，不是原文的唯一故事。保险的代价（税收扭曲、被原文点到的激励）未展开成完整的道德风险模型。</p><h3 id="与主干挤兑课的分工" tabindex="-1">与主干挤兑课的分工 <a class="header-anchor" href="#与主干挤兑课的分工" aria-label="Permalink to &quot;与主干挤兑课的分工&quot;">​</a></h3><p>主干<a href="/econ/diamond-dybvig">Diamond–Dybvig 挤兑</a>已取双均衡与序贯服务。本篇对照 <em>JPE</em> 91(3) 1983：激励相容、加总确定性、标题里的保险与流动性是同一件家具。真实三期，无准备金、无 Woodford 利率规则、无巴塞尔。批发融资与 LCR 是类比，不是这篇的定理。读完可回主干挤兑与中介课；不要把附录十篇当成连续主干的第十单元，也不接在<a href="/econ/to-limit-order-book">到限价簿</a>之后。</p><p><span class="marginnote">Diamond and Dybvig, <em>Journal of Political Economy</em> 91(3), 1983, 401–419。不要发明 arXiv 编号。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1983 写成货币乘数或最后贷款人操作手册。Bagehot 的窗口在主干<a href="/econ/lender-of-last-resort">最后贷款人</a>；原文几乎没有央行。也不要把「太阳黑子挤兑」说成作者否认基本面挤兑——他们选择最干净的环境来证明合同本身足够。全球博弈（Morris–Shin、Rochet–Vives）是后二十年的精炼，不在这篇 <em>JPE</em> 里。</p><p>宏观与货币附录到此结束。主干若只读挤兑课，已经够用机制；读原文是为了对保险与暂停在博弈里的对称位置，以及模型刻意不含的货币。</p><p>激励相容要求耐心者不假装急躁。加总确定性使好均衡的资源约束是确定的。比例随机、基本面触发，是后继文献。</p><p>序贯服务是制度选择。同步按比例结算可以设计掉坏均衡；原文选择不设计掉，正因为活期接近序贯。</p><p>不要把 2008 年批发融资写成 1983 年的定理。转换功能可以换负债合同，文献不是同一篇。</p><p>本篇结束附录链。量化栏从 <a href="/quant/lob-structure">LOB</a> 起，不从本篇起。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Diamond–Dybvig 1983：保险与暂停是删掉坏均衡的工具，与合同配套。</li><li>银行可以是被动资产池；挤兑不必有坏资产消息。</li><li>无准备金、无利率规则；不要译成 Woodford 或巴塞尔。</li><li>出处：Diamond and Dybvig, <em>JPE</em> 1983。</li></ul>',14))])}const B=n(E,[["render",c]]);export{_ as __pageData,B as default};
